importScripts('/cache-version.js','/engine.js','/optimizer-core.js');
const memory=new Map();let dbPromise;
function database(){return dbPromise??=new Promise(resolve=>{if(!self.indexedDB){resolve(null);return}const req=indexedDB.open('stack-lab-dps-cache',1);req.onupgradeneeded=()=>req.result.createObjectStore('results',{keyPath:'key'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null);req.onblocked=()=>resolve(null)})}
async function cacheKey(input){const bytes=new TextEncoder().encode(CoopOptimize.cacheInput(input,COOP_DATA_REVISION));const hash=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(hash),v=>v.toString(16).padStart(2,'0')).join('')}
async function read(key){if(memory.has(key))return memory.get(key);const db=await database();if(!db)return;return new Promise(resolve=>{try{const req=db.transaction('results').objectStore('results').get(key);req.onsuccess=()=>resolve(req.result?.result);req.onerror=()=>resolve()}catch{resolve()}})}
async function write(key,result){memory.set(key,result);if(memory.size>300)memory.delete(memory.keys().next().value);const db=await database();if(!db)return;await new Promise(resolve=>{try{const tx=db.transaction('results','readwrite'),store=tx.objectStore('results');store.put({key,result,created:Date.now()});const req=store.count();req.onsuccess=()=>{let extra=req.result-1500;if(extra>0){const cursor=store.openCursor();cursor.onsuccess=()=>{const item=cursor.result;if(item&&extra-->0){item.delete();item.continue()}}}};tx.oncomplete=tx.onerror=tx.onabort=()=>resolve()}catch{resolve()}})}
async function calculate(input){const key=await cacheKey(input),saved=await read(key);if(saved)return{...saved,cached:true};const {cells,you,partner,mode,target}=input,p={...you,mode,targetId:target},other={...partner,mode,targetId:target};const t=CoopTargets.TARGET_BY_ID.get(target);if(!t)throw Error('계산 대상을 찾을 수 없습니다.');p.wave=t.wave;other.wave=t.wave;const r=CoopBoss.computeBossBoard(cells,p,{marks:input.marks||[],range:{},blackout:'auto',builds:{you:p,partner:other},gold:false,bounties:null});const actual=CoopBoss.runActual(r);if(!Number.isFinite(actual)||actual<0||!Number.isFinite(r.dps))throw Error('유효한 DPS를 계산할 수 없습니다.');const result={actual,theory:r.dps,seconds:Number.isFinite(r.kill.seconds)?r.kill.seconds:null,window:r.kill.event?.window,units:r.units.map(u=>({slug:u.placement.slug,row:u.placement.row,col:u.placement.col,liberated:u.liberated,dps:u.dps,range:u.range,cover:u.cover,stats:u.result?{level:u.result.stats.level,lib:u.result.stats.lib}:null}))};await write(key,result);return{...result,cached:false}}
self.onmessage=async({data})=>{const{id,kind='calculate'}=data;try{if(kind==='optimize'){const tiles=Object.fromEntries(['you','partner'].map(s=>[s,CoopGeometry.tilesOf(s).map(({row,col})=>({row,col}))]));const r=await CoopOptimize.optimize({cells:data.cells,marks:data.marks||[],tiles,evaluate:(cells,marks)=>calculate({...data,cells,marks}),maxEvaluations:data.depth==='deep'?600:160,timeLimit:data.depth==='deep'?40000:12000,onProgress:progress=>postMessage({kind:'progress',id,...progress})});postMessage({kind:'optimized',id,...r})}else postMessage({id,...await calculate(data)})}catch(e){postMessage({id,kind,error:e.message})}};
